	ProcurementErrorReasonRateLimited                 = ProcurementErrorReason{Code: "RATE_LIMITED", Value: "RATE_LIMITED", Label: "請求過於頻繁", Description: "429。可重試性由 `Retry-After` header 表達（串流路徑因 header 已 flush，改由 error frame 帶延遲）"}
	ProcurementErrorReasonCapabilityUnavailable       = ProcurementErrorReason{Code: "CAPABILITY_UNAVAILABLE", Value: "CAPABILITY_UNAVAILABLE", Label: "功能暫不可用", Description: "503。capability 關閉時的 typed failure，不得靜默降級成舊行為"}
	ProcurementErrorReasonSchemaVersionUnsupported    = ProcurementErrorReason{Code: "SCHEMA_VERSION_UNSUPPORTED", Value: "SCHEMA_VERSION_UNSUPPORTED", Label: "版本不支援", Description: "400。client 要求的 major schema 版本不受支援"}
	ProcurementErrorReasonRequestNotFound             = ProcurementErrorReason{Code: "REQUEST_NOT_FOUND", Value: "REQUEST_NOT_FOUND", Label: "需求不存在", Description: "404。採購需求不存在或不屬於此買家"}
	ProcurementErrorReasonIdempotencyKeyConflict      = ProcurementErrorReason{Code: "IDEMPOTENCY_KEY_CONFLICT", Value: "IDEMPOTENCY_KEY_CONFLICT", Label: "冪等鍵衝突", Description: "409。同一 clientRequestId 已綁定另一份 payload。**不是** #2446 原文的 IDEMPOTENCY_KEY_REUSED——單純 reuse（同鍵同內容）在本系統是成功的 replay 路徑，用 REUSED 命名等於拿正常路徑的名字命名錯誤"}
