	ProcurementErrorReasonRequirementNotReady         = ProcurementErrorReason{Code: "REQUIREMENT_NOT_READY", Value: "REQUIREMENT_NOT_READY", Label: "需求尚未齊備", Description: "409。必填欄位未填滿即嘗試進入候選比對"}
	ProcurementErrorReasonAnswerSchemaInvalid         = ProcurementErrorReason{Code: "ANSWER_SCHEMA_INVALID", Value: "ANSWER_SCHEMA_INVALID", Label: "回答格式不符", Description: "422。答案不符合該問題卡的 schema（例如複合問題缺 unitOptionId）"}
