	ProcurementErrorReasonCropChoiceInvalid           = ProcurementErrorReason{Code: "CROP_CHOICE_INVALID", Value: "CROP_CHOICE_INVALID", Label: "品項選擇無效", Description: "422。crop-disambiguation 選項不在可選集合內"}
	ProcurementErrorReasonInputTooLong                = ProcurementErrorReason{Code: "INPUT_TOO_LONG", Value: "INPUT_TOO_LONG", Label: "輸入過長", Description: "422。訊息或自由文字超過長度上限"}
	ProcurementErrorReasonAgentMonthlyQuotaExceeded   = ProcurementErrorReason{Code: "AGENT_MONTHLY_QUOTA_EXCEEDED", Value: "AGENT_MONTHLY_QUOTA_EXCEEDED", Label: "本月 Agent 額度已用完", Description: "429。本月額度已用盡，回 remaining=0 與 resetAt（下期起始時間）——doc 57 §7"}
	ProcurementErrorReasonInvalidOverride             = ProcurementErrorReason{Code: "INVALID_OVERRIDE", Value: "INVALID_OVERRIDE", Label: "覆寫欄位無效", Description: "400。報價單邀請的買家覆寫欄位格式或值不合法"}
	ProcurementErrorReasonConversationTitleInvalid    = ProcurementErrorReason{Code: "CONVERSATION_TITLE_INVALID", Value: "CONVERSATION_TITLE_INVALID", Label: "對話標題無效", Description: "422。改名的標題為空或超長"}
