	ProcurementErrorReasonLaneMismatch                = ProcurementErrorReason{Code: "LANE_MISMATCH", Value: "LANE_MISMATCH", Label: "通道不符", Description: "400。指定的 lane 與候選實際所屬通道不一致"}
