	ProcurementErrorReasonInterruptExpired            = ProcurementErrorReason{Code: "INTERRUPT_EXPIRED", Value: "INTERRUPT_EXPIRED", Label: "中斷已逾期", Description: "409。resume 命令對應的 interrupt 已超過 expiresAt"}
