	ProcurementErrorReasonReplayCursorExpired         = ProcurementErrorReason{Code: "REPLAY_CURSOR_EXPIRED", Value: "REPLAY_CURSOR_EXPIRED", Label: "Replay 游標已過期", Description: "410。GET replay 的 Last-Event-ID 早於 minAvailableSeqId"}
	ProcurementErrorReasonReplayCursorAhead           = ProcurementErrorReason{Code: "REPLAY_CURSOR_AHEAD", Value: "REPLAY_CURSOR_AHEAD", Label: "Replay 游標超前", Description: "409。GET replay 的 Last-Event-ID 高於目前 high-water mark"}
