	ProcurementErrorReasonRunResultNotReady           = ProcurementErrorReason{Code: "RUN_RESULT_NOT_READY", Value: "RUN_RESULT_NOT_READY", Label: "Run 結果尚未就緒", Description: "422（#3330 起；原為 503 —— 服務端改用 codes.FailedPrecondition，而 procurement 走自己的對照表 gateway/internal/procurement/wire.go，那裡 FailedPrecondition 映 422、409 留給 Aborted）。命令的冪等鍵命中一個已建立的 run，但該 run 沒有可重播的結果。**兩種成因、處置相反，呼叫端不得一律重試**：(1) run 仍在執行中 → 稍後重試**同一把** clientRequestId 可能就緒；(2) run 已以 FAILED 收尾 → 該鍵永遠不會再產生可重播結果，必須改用**新的** clientRequestId 重下命令，重試同一把鍵會無限迴圈。本碼本身不區分兩者（區分需要讀 run 狀態），呼叫端若要自動重試必須設重試上限，或改查 run 狀態再決定。與 `RUN_NOT_ACTIVE` 是兩件事：那個講的是「run 的狀態不允許這個命令」，這個講的是「命令已受理、但沒有結果可回」"}
	ProcurementErrorReasonApprovalPending             = ProcurementErrorReason{Code: "APPROVAL_PENDING", Value: "APPROVAL_PENDING", Label: "待回覆的中斷", Description: "409。該需求有一個尚未回覆的 interrupt（run 停在 WAITING_FOR_INPUT），必須改用 POST /runs/{runId}/resume 回覆；/answers 與 /crop-disambiguation 在此期間不得直接寫入，否則會讓 interrupt 孤兒化"}
	ProcurementErrorReasonStaleRfqSnapshot            = ProcurementErrorReason{Code: "STALE_RFQ_SNAPSHOT", Value: "STALE_RFQ_SNAPSHOT", Label: "詢價快照已過期", Description: "409。acceptance 的 expectedRfqSnapshotHash 與現行 confirmed snapshot 不符（需求被其他裝置改過）。零 side effect，不建立任何 acceptance 列（doc 64 §9.2，#2538）"}
	ProcurementErrorReasonStalePublication            = ProcurementErrorReason{Code: "STALE_PUBLICATION", Value: "STALE_PUBLICATION", Label: "發布依據已過期", Description: "409。賣家回價命令帶的 publication id／version／sellerFacingPayloadHash 與現行不符。零 side effect（doc 64 §9.2，#2538）"}
	ProcurementErrorReasonStaleSellerResponse         = ProcurementErrorReason{Code: "STALE_SELLER_RESPONSE", Value: "STALE_SELLER_RESPONSE", Label: "供應商報價已變動", Description: "409。expectedSellerResponseVersion 不是目前版本——賣家已改價或已撤回。⛔ **必須明確告知使用者報價已變動，不得靜默改用最新版重試**（doc 64 §9.2，#2538）"}
	ProcurementErrorReasonRfqResponseAlreadySubmitted = ProcurementErrorReason{Code: "RFQ_RESPONSE_ALREADY_SUBMITTED", Value: "RFQ_RESPONSE_ALREADY_SUBMITTED", Label: "已提交過正式回價", Description: "409。賣家帶著「尚無正式回價」的 CAS（空 expectedSellerResponseVersion）提交，但該 publication 上已有一版。改版要帶目前版本（v6.0 Part III §13.1，#2538）"}
	ProcurementErrorReasonRfqResponseExpired          = ProcurementErrorReason{Code: "RFQ_RESPONSE_EXPIRED", Value: "RFQ_RESPONSE_EXPIRED", Label: "報價已逾有效期", Description: "409。被 shortlist 或被接受的 sellerResponseVersion 已過 validUntil。⛔ 不可接受，也不得自動改接受別版（v6.0 Part III §13.1，#2538）"}
	ProcurementErrorReasonRfqRecipientClosed          = ProcurementErrorReason{Code: "RFQ_RECIPIENT_CLOSED", Value: "RFQ_RECIPIENT_CLOSED", Label: "該收件人已停止寫入", Description: "409。賣家已明確拒絕（decline），或 publication 已結案／他人成交後停止寫入（v6.0 Part III §13.1，#2538）"}
	ProcurementErrorReasonRfqCheckoutAlreadyActive    = ProcurementErrorReason{Code: "RFQ_CHECKOUT_ALREADY_ACTIVE", Value: "RFQ_CHECKOUT_ALREADY_ACTIVE", Label: "已有進行中的成交", Description: "409。同一 request 已有 ACTIVE 的 acceptance。回既有 orderNo 讓買家去付款，**不是**叫他重新接受（v6.0 Part III §13.1，#2538）"}
	ProcurementErrorReasonRfqAlreadyAwarded           = ProcurementErrorReason{Code: "RFQ_ALREADY_AWARDED", Value: "RFQ_ALREADY_AWARDED", Label: "本詢價已成交", Description: "409。同一 request 已有 payment-finalized 的成交。這是真正的終局封鎖，與 RFQ_CHECKOUT_ALREADY_ACTIVE 的差別是後者仍可付款、本碼不可（v6.0 Part III §13.1，#2538）"}
	ProcurementErrorReasonQuoteAmountInconsistent     = ProcurementErrorReason{Code: "QUOTE_AMOUNT_INCONSISTENT", Value: "QUOTE_AMOUNT_INCONSISTENT", Label: "報價金額不一致", Description: "422。totalAmount ≠ goodsAmount + shippingAmount + taxAmount，或金額／幣別無法 canonicalize。零 side effect，不建立版本列（#2538）"}
