	InvoiceProviderAccountStatusCredentialVerifying = InvoiceProviderAccountStatus{Code: "CREDENTIAL_VERIFYING", Value: "CREDENTIAL_VERIFYING", Label: "驗證中", Description: "正在打 AMEGO 驗簽章、統編與字軌"}
	InvoiceProviderAccountStatusActive              = InvoiceProviderAccountStatus{Code: "ACTIVE", Value: "ACTIVE", Label: "已啟用", Description: "三項驗證全過且至少一組可用字軌；可設定自動開立切點"}
	InvoiceProviderAccountStatusInvalidCredential   = InvoiceProviderAccountStatus{Code: "INVALID_CREDENTIAL", Value: "INVALID_CREDENTIAL", Label: "憑證錯誤", Description: "簽章或統編不符（AMEGO code 16／12）；賣家重新輸入即可修復"}
	InvoiceProviderAccountStatusProviderRejected    = InvoiceProviderAccountStatus{Code: "PROVIDER_REJECTED", Value: "PROVIDER_REJECTED", Label: "服務商拒絕", Description: "帳號未啟用／停權／未申請 API（code 13／19／22）；需回光貿後台處理"}
	InvoiceProviderAccountStatusProviderUnavailable = InvoiceProviderAccountStatus{Code: "PROVIDER_UNAVAILABLE", Value: "PROVIDER_UNAVAILABLE", Label: "服務商無法連線", Description: "停機維護或逾時（code 10／18／21）；排入 15 分鐘一次自動重驗"}
	InvoiceProviderAccountStatusRotationPending     = InvoiceProviderAccountStatus{Code: "ROTATION_PENDING", Value: "ROTATION_PENDING", Label: "憑證輪替中", Description: "新舊 key 並存；驗證失敗一律保留原 key"}
