	InvoiceCorrectionRejectReasonPastVoidDeadline      = InvoiceCorrectionRejectReason{Code: "PAST_VOID_DEADLINE", Value: "PAST_VOID_DEADLINE", Label: "已逾可作廢期限", Description: "超過法定可作廢期間；對應 AMEGO f0501 的 3050126"}
	InvoiceCorrectionRejectReasonAllowanceExists       = InvoiceCorrectionRejectReason{Code: "ALLOWANCE_EXISTS", Value: "ALLOWANCE_EXISTS", Label: "已存在折讓", Description: "該張發票已有折讓單，作廢會使折讓失去依據；對應 AMEGO f0501 的 3050141"}
	InvoiceCorrectionRejectReasonTrackInsufficient     = InvoiceCorrectionRejectReason{Code: "TRACK_INSUFFICIENT", Value: "TRACK_INSUFFICIENT", Label: "字軌餘量不足", Description: "重開需要一個新號碼而目前配號不足；先確保可開再作廢，故在作廢前就擋下"}
	InvoiceCorrectionRejectReasonCarrierInvalid        = InvoiceCorrectionRejectReason{Code: "CARRIER_INVALID", Value: "CARRIER_INVALID", Label: "載具無效", Description: "更正後的載具驗證不通過，重開會失敗"}
	InvoiceCorrectionRejectReasonProviderUnavailable   = InvoiceCorrectionRejectReason{Code: "PROVIDER_UNAVAILABLE", Value: "PROVIDER_UNAVAILABLE", Label: "服務商暫時無法連線", Description: "電子發票服務商當下不可用；買家稍後可再申請一次（REJECTED 是終態且不佔 uq_invcorr_open_per_document 的名額）"}
	InvoiceCorrectionRejectReasonProviderStateConflict = InvoiceCorrectionRejectReason{Code: "PROVIDER_STATE_CONFLICT", Value: "PROVIDER_STATE_CONFLICT", Label: "發票狀態衝突，請聯繫客服", Description: "AMEGO f0501 回 `3050123`「指定發票號碼**已存在註銷**」——那張發票在服務商端已有一筆註銷紀錄，我方的作廢因此走不下去。⚠️ 這**不是**「已申報」：註銷與作廢是兩種不同動作（AMEGO 另有 `3050122`「已存在開立作廢」，我方視為成功等價）。**買家手上的原發票不受影響**，只是內容改不了"}
