	LedgerAccountCodePlatformFeeExpense             = LedgerAccountCode{Code: "PLATFORM_FEE_EXPENSE", Value: "PLATFORM_FEE_EXPENSE", Label: "平台手續費支出", Description: "平台對外支付的費用"}
	LedgerAccountCodePlatformLogisticsCost          = LedgerAccountCode{Code: "PLATFORM_LOGISTICS_COST", Value: "PLATFORM_LOGISTICS_COST", Label: "平台物流成本", Description: "平台負擔的物流費用"}
	LedgerAccountCodeSellerPayable                  = LedgerAccountCode{Code: "SELLER_PAYABLE", Value: "SELLER_PAYABLE", Label: "應付賣家", Description: "賣家淨額的主科目"}
