	LedgerAccountCodeSellerManualAdjustment         = LedgerAccountCode{Code: "SELLER_MANUAL_ADJUSTMENT", Value: "SELLER_MANUAL_ADJUSTMENT", Label: "賣家可稽核調整", Description: "手動調整必須帶原因與依據"}
	LedgerAccountCodeProviderPayable                = LedgerAccountCode{Code: "PROVIDER_PAYABLE", Value: "PROVIDER_PAYABLE", Label: "應付物流商", Description: "provider 對帳用"}
	LedgerAccountCodeSellerLogisticsReceivable      = LedgerAccountCode{Code: "SELLER_LOGISTICS_RECEIVABLE", Value: "SELLER_LOGISTICS_RECEIVABLE", Label: "賣家物流應收", Description: "借方增加＝應收成立；貸方增加＝收款完成／貸記沖抵。🔴 與 SELLER_LOGISTICS_CREDIT 是**兩個科目**不是一個科目的正負——兩者可同時存在（這期欠、上期多收），合成淨額會讓 ADR-008 第 1 條保證失效"}
	LedgerAccountCodePlatformLogisticsServiceIncome = LedgerAccountCode{Code: "PLATFORM_LOGISTICS_SERVICE_INCOME", Value: "PLATFORM_LOGISTICS_SERVICE_INCOME", Label: "平台物流服務費收入", Description: "貸方增加＝平台向賣家收的物流服務費收入。🔴 不等於買家付的運費（那是 PLATFORM_LOGISTICS_RECOVERY），ADR-006 三條線互不推導"}
	LedgerAccountCodePlatformCollectionFeeExpense   = LedgerAccountCode{Code: "PLATFORM_COLLECTION_FEE_EXPENSE", Value: "PLATFORM_COLLECTION_FEE_EXPENSE", Label: "平台收款通道手續費", Description: "🔴 **僅限平台負擔的例外情況**（PLATFORM_CAUSED 的反向沖銷）。正常路徑**不 post 這一筆**——手續費由賣家負擔（ADR-005），對平台不是費用而是「應收未收足的原因」，多 post 一筆會把應收餘額沖平、讓 ADR-011 的結轉機制在帳上失效"}
