	LedgerTxnTypeRefundReversalShipping     = LedgerTxnType{Code: "REFUND_REVERSAL_SHIPPING", Value: "REFUND_REVERSAL_SHIPPING", Label: "運費退款沖銷", Description: "🔴 **不**進 `fee_base`"}
	LedgerTxnTypePayoutFee                  = LedgerTxnType{Code: "PAYOUT_FEE", Value: "PAYOUT_FEE", Label: "撥款指示費", Description: "費率與費基於指示落地時快照，事後可重算"}
	LedgerTxnTypePlatformServiceFee         = LedgerTxnType{Code: "PLATFORM_SERVICE_FEE", Value: "PLATFORM_SERVICE_FEE", Label: "平台服務費", Description: "合約約定的服務費"}
	LedgerTxnTypeHoldApply                  = LedgerTxnType{Code: "HOLD_APPLY", Value: "HOLD_APPLY", Label: "保留款設定", Description: "暫停撥款"}
	LedgerTxnTypeHoldRelease                = LedgerTxnType{Code: "HOLD_RELEASE", Value: "HOLD_RELEASE", Label: "保留款解除", Description: "解除暫停"}
	LedgerTxnTypePayoutSettle               = LedgerTxnType{Code: "PAYOUT_SETTLE", Value: "PAYOUT_SETTLE", Label: "撥款結清", Description: "撥款指示完成"}
	LedgerTxnTypeManualAdjustment           = LedgerTxnType{Code: "MANUAL_ADJUSTMENT", Value: "MANUAL_ADJUSTMENT", Label: "可稽核調整", Description: "必填原因與依據"}
	LedgerTxnTypeLogisticsCostAccrual       = LedgerTxnType{Code: "LOGISTICS_COST_ACCRUAL", Value: "LOGISTICS_COST_ACCRUAL", Label: "物流成本應計", Description: "平台側物流成本"}
	LedgerTxnTypeProviderSettlement         = LedgerTxnType{Code: "PROVIDER_SETTLEMENT", Value: "PROVIDER_SETTLEMENT", Label: "物流商結算", Description: "provider 帳單對帳"}
	LedgerTxnTypeLogisticsReceivableAccrual = LedgerTxnType{Code: "LOGISTICS_RECEIVABLE_ACCRUAL", Value: "LOGISTICS_RECEIVABLE_ACCRUAL", Label: "物流應收認列", Description: "DEBIT SELLER_LOGISTICS_RECEIVABLE／CREDIT PLATFORM_LOGISTICS_SERVICE_INCOME。🔴 金額＝本期成本 − 平台補貼，**不含前期結轉**（結轉是前期已認列、尚未收足的餘額，再認列一次就是重複認列收入）"}
