	ModerationActionTypeBanUser    = ModerationActionType{Code: "BAN_USER", Value: "BAN_USER", Label: "停權使用者", Description: "對應 `ReportResolveAction.BAN_USER`"}
	ModerationActionTypeDismiss    = ModerationActionType{Code: "DISMISS", Value: "DISMISS", Label: "駁回檢舉", Description: "對應 `ReportResolveAction.DISMISS`"}
	ModerationActionTypeReopen     = ModerationActionType{Code: "REOPEN", Value: "REOPEN", Label: "重開申訴", Description: "被處置者申訴後由管理員重開，檢舉單轉 `APPEALED`；不是終態裁決，故不存在於 `ReportResolveAction`"}
