// ===== InvoiceComplaintAction =====
// 申訴時間軸上「誰選了哪個動作」。⚠️ **與 `InvoiceComplaintEventType` 是同一張表的兩個正交欄位、不是二選一**：`event_type` 答「發生了什麼」（含系統自動事件），`action` 答「賣家或 ADM 在畫面上點了哪一顆」。沒有人做選擇的列（買家提申訴、SLA 逾期、逾時自動升級、**買家不接受（端點 63）**、買家撤回、買家重開）`action` 為 NULL——**買家的動作一律不進本軸**，本 enum 只裝賣家與 ADM 在畫面上點的按鈕。⚠️ ADM 端點 60 的另外兩個 action（`REQUEST_REWORK`／`RECOMMEND_SUSPENSION`）**刻意不寫時間軸**——前者副作用只有重置 SLA，後者只寫建議與稽核（`invoice_admin_audit_logs`），所以本表是 6 值不是 8 值。

type InvoiceComplaintAction struct {
	Code        string
	Value       string
	Label       string
	Description string
}

var (
	InvoiceComplaintActionResent           = InvoiceComplaintAction{Code: "RESENT", Value: "RESENT", Label: "已重新寄送", Description: "actor = SELLER；端點 36。原發票存在，賣家重寄通知／載具"}
	InvoiceComplaintActionReissued         = InvoiceComplaintAction{Code: "REISSUED", Value: "REISSUED", Label: "已補開或更正", Description: "actor = SELLER；端點 36"}
	InvoiceComplaintActionNeedPlatformHelp = InvoiceComplaintAction{Code: "NEED_PLATFORM_HELP", Value: "NEED_PLATFORM_HELP", Label: "需要平台協助", Description: "actor = SELLER；端點 36。必填說明，同時把案件推進 `ESCALATED_TO_ADM`（58 §7 K03）"}
	InvoiceComplaintActionReminded         = InvoiceComplaintAction{Code: "REMINDED", Value: "REMINDED", Label: "平台已提醒賣家", Description: "actor = ADMIN；端點 60 的 `REMIND_SELLER`。不改變狀態也不改變 SLA"}
	InvoiceComplaintActionDecidedResolved  = InvoiceComplaintAction{Code: "DECIDED_RESOLVED", Value: "DECIDED_RESOLVED", Label: "平台判定已解決", Description: "actor = ADMIN；端點 60 的 `DECIDE_RESOLVED`（58 §7 K08）"}
	InvoiceComplaintActionDecidedViolation = InvoiceComplaintAction{Code: "DECIDED_VIOLATION", Value: "DECIDED_VIOLATION", Label: "平台判定賣家違規", Description: "actor = ADMIN；端點 60 的 `DECIDE_VIOLATION`（58 §7 K09）。**只有這個值計入 90 天違規計數**"}
)

var AllInvoiceComplaintActions = []InvoiceComplaintAction{
	InvoiceComplaintActionResent,
	InvoiceComplaintActionReissued,
	InvoiceComplaintActionNeedPlatformHelp,
	InvoiceComplaintActionReminded,
	InvoiceComplaintActionDecidedResolved,
	InvoiceComplaintActionDecidedViolation,
}

func InvoiceComplaintActionFromCode(code string) (InvoiceComplaintAction, bool) {
	for _, v := range AllInvoiceComplaintActions {
		if v.Code == code {
			return v, true
		}
	}
	return InvoiceComplaintAction{}, false
}

func InvoiceComplaintActionFromValue(value string) (InvoiceComplaintAction, bool) {
	for _, v := range AllInvoiceComplaintActions {
		if v.Value == value {
			return v, true
		}
	}
	return InvoiceComplaintAction{}, false
}

// ===== InvoiceDocumentTimelineEvent =====
// 一張稅務文件的**買家可見歷程**事件。🔴 **它不是 `InvoiceEventType`**——那是 MQ 事件型別（12 值、全部 `INVOICE_` 開頭、前端可見 No、不進任何 allowlist），兩者**交集為空**；把本欄的值拿去查 `InvoiceEventType` 的表只會查不到而顯示空白（`codeLabel` 查不到不報錯）。本值域是 `invoice_status_history` 的**投影**：後端組 `timeline[]` 時把三個 `subject_type` 的狀態轉移摺疊成買家看得懂的五件事，一個轉移最多產生一列。⚠️ 五值刻意**不含失敗與處理中**（`ISSUING`／`ISSUE_FAILED`／`AWAITING_MANUAL` 等內部階段）——買家端對這些的呈現由 `state` ＋ `stateNotice` 承擔（58 §6.1.3），時間軸只記「已經成立的法定事實」。

type InvoiceDocumentTimelineEvent struct {
	Code        string
	Value       string
	Label       string
	Description string
}

var (
	InvoiceDocumentTimelineEventIssued           = InvoiceDocumentTimelineEvent{Code: "ISSUED", Value: "ISSUED", Label: "已開立", Description: "投影自 `subject_type='DOCUMENT'` 且 `to_status='ISSUED'`（58 §7.3.1）"}
	InvoiceDocumentTimelineEventUpdated          = InvoiceDocumentTimelineEvent{Code: "UPDATED", Value: "UPDATED", Label: "已修改", Description: "投影自 `subject_type='CORRECTION_REQUEST'` 且 `to_status='UPDATED_BEFORE_ISSUE'`（58 §7.3.6 **R03**，開票前改快照）"}
	InvoiceDocumentTimelineEventVoided           = InvoiceDocumentTimelineEvent{Code: "VOIDED", Value: "VOIDED", Label: "已作廢", Description: "投影自 `subject_type='DOCUMENT'` 且 `to_status='VOIDED'`（58 §7.3.1；該轉態由 §7.3.7 **G09** 的作廢副作用寫入）"}
	InvoiceDocumentTimelineEventReissued         = InvoiceDocumentTimelineEvent{Code: "REISSUED", Value: "REISSUED", Label: "已重新開立", Description: "投影自 `subject_type='DOCUMENT'` 且 `to_status='SUPERSEDED'`（58 §7.3.1「重開文件轉 `ISSUED`」那一列）。⚠️ 這一列落在**舊文件**的時間軸上；新文件的時間軸只有它自己的 `ISSUED`"}
	InvoiceDocumentTimelineEventAllowanceApplied = InvoiceDocumentTimelineEvent{Code: "ALLOWANCE_APPLIED", Value: "ALLOWANCE_APPLIED", Label: "已開立折讓", Description: "投影自 `subject_type='ADJUSTMENT'` 且 `to_status='COMPLETED'`，並要求該 `invoice_adjustments.adjustment_type='ALLOWANCE'` 且 `document_id` ＝本文件（58 §7.3.7 **G09**／**G13**／**G17**）"}
)

var AllInvoiceDocumentTimelineEvents = []InvoiceDocumentTimelineEvent{
	InvoiceDocumentTimelineEventIssued,
	InvoiceDocumentTimelineEventUpdated,
	InvoiceDocumentTimelineEventVoided,
	InvoiceDocumentTimelineEventReissued,
	InvoiceDocumentTimelineEventAllowanceApplied,
}

func InvoiceDocumentTimelineEventFromCode(code string) (InvoiceDocumentTimelineEvent, bool) {
	for _, v := range AllInvoiceDocumentTimelineEvents {
		if v.Code == code {
			return v, true
		}
	}
	return InvoiceDocumentTimelineEvent{}, false
}

func InvoiceDocumentTimelineEventFromValue(value string) (InvoiceDocumentTimelineEvent, bool) {
	for _, v := range AllInvoiceDocumentTimelineEvents {
		if v.Value == value {
			return v, true
		}
	}
	return InvoiceDocumentTimelineEvent{}, false
}
